// Fails when a long dash (em or en) appears in code, docs or copy. Use a comma, colon, period or hyphen instead.
import { execFileSync } from "node:child_process"
import { readFileSync } from "node:fs"

const LONG_DASHES = [8211, 8212].map((code) => String.fromCharCode(code))
// AGENTS.md is regenerated by `next dev` with its own wording, so it cannot be held to this rule.
const SKIP = [/^package-lock\.json$/, /^docs\/reference\//, /^public\//, /^AGENTS\.md$/]

const files = execFileSync("git", ["ls-files", "--cached", "--others", "--exclude-standard"], { encoding: "utf8" })
  .split("\n")
  .filter((file) => file && !SKIP.some((pattern) => pattern.test(file)))

const offenders = files.flatMap((file) => {
  let text
  try {
    text = readFileSync(file, "utf8")
  } catch {
    return []
  }
  return text
    .split("\n")
    .map((line, index) => (LONG_DASHES.some((dash) => line.includes(dash)) ? `${file}:${index + 1}` : null))
    .filter(Boolean)
})

if (offenders.length > 0) {
  console.error(`Long dashes found. Replace them with a comma, colon, period or hyphen:\n${offenders.join("\n")}`)
  process.exit(1)
}

console.log("No long dashes found.")
